var _markdown = "\n\n`Screen.h` · `plugin::screen`\n\n把设计分辨率上的坐标换算到当前屏幕分辨率。\n\n## 设计坐标换算 [#设计坐标换算]\n\n<Api name=\"GetCoord 族\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static float GetCoord(float a);\n      static float GetCoordLeft(float a);\n      static float GetCoordRight(float a);\n      static float GetCoordTop(float a);\n      static float GetCoordBottom(float a);\n      static float GetCoordCenterLeft(float a);\n      static float GetCoordCenterRight(float a);\n      static float GetCoordCenterUp(float a);\n      static float GetCoordCenterDown(float a);\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      float x = plugin::screen::GetCoordLeft(20.0f);\n      float y = plugin::screen::GetCoordTop(20.0f);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 倍率与设计基准 [#倍率与设计基准]\n\n<Api name=\"GetMultiplier / SetBaseResolution\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static float GetMultiplier(float a);\n      static void SetBaseResolution(float res);\n      static float GetBaseResolution();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      plugin::screen::SetBaseResolution(1080.0f);\n      float scale = plugin::screen::GetMultiplier(1.0f);\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 当前分辨率 [#当前分辨率]\n\n<Api name=\"GetScreenWidth / Height / Center / Max\">\n  <CodeBlockTabs defaultValue=\"签名\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"签名\">\n        签名\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"示例\">\n        示例\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"签名\">\n      ```cpp\n      static float GetScreenWidth();\n      static float GetScreenHeight();\n      static float GetScreenCenterX();\n      static float GetScreenCenterY();\n      static float GetScreenMaxX();\n      static float GetScreenMaxY();\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"示例\">\n      ```cpp\n      float w = plugin::screen::GetScreenWidth();\n      float h = plugin::screen::GetScreenHeight();\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Api>\n\n## 屏幕坐标宏 [#屏幕坐标宏]\n\n<CodeBlockTabs defaultValue=\"签名\">\n  <CodeBlockTabsList>\n    <CodeBlockTabsTrigger value=\"签名\">\n      签名\n    </CodeBlockTabsTrigger>\n\n    <CodeBlockTabsTrigger value=\"示例\">\n      示例\n    </CodeBlockTabsTrigger>\n  </CodeBlockTabsList>\n\n  <CodeBlockTab value=\"签名\">\n    ```cpp\n    SCREEN_COORD(a)\n    SCREEN_COORD_LEFT(a) // RIGHT TOP BOTTOM\n    SCREEN_WIDTH SCREEN_HEIGHT\n    SCREEN_RECT(l, t, r, b)\n    ```\n  </CodeBlockTab>\n\n  <CodeBlockTab value=\"示例\">\n    ```cpp\n    #include \"extensions/Screen.h\"\n\n    plugin::Events::drawingEvent += [] {\n        float x = SCREEN_COORD_LEFT(20.0f);\n        CRect rect = SCREEN_RECT(10.0f, 10.0f, 200.0f, 80.0f);\n        (void)x;\n        (void)rect;\n    };\n    ```\n  </CodeBlockTab>\n</CodeBlockTabs>\n";
